import os
for dirpath, dirs, files in os.walk('/workspace/repo-vul/src-vul'):
    # include third party
    for f in files:
        if f.endswith(('.c','.h','.cc','.cpp','.inc')):
            path=os.path.join(dirpath,f)
            try: text=open(path,errors='ignore').read()
            except: continue
            if 'get_unaligned_be16' in text or 'load_u16_unaligned' in text or 'libdeflate_zlib_decompress_ex' in text:
                print(path)
                for i,l in enumerate(text.splitlines(),1):
                    if 'get_unaligned_be16' in l or 'load_u16_unaligned' in l or 'zlib_decompress_ex' in l:
                        print(i,l[:180])
